// Estland: GeoJSON-FeatureCollection, ED-269-Felder in properties, geometry dort ein OBJEKT.
const eeFeat = (props) => ({
  type: 'Feature',
  geometry: props.geometry.horizontalProjection,
  properties: props,
});
